import inspect

# no defaults
sig = inspect.signature(scheme_frontier)
assert all(p.default is inspect.Parameter.empty for p in sig.parameters.values()), sig

# brute-force cross-check
def all_candidates(capacity):
    cands = []
    if capacity == 1:
        cands.append(profile("lamport"))
        for w in (4, 8):
            cands.append(profile("wots", w=w))
    for w in (4, 8):
        for h in range(1, 9):
            c = profile("merkle", w=w, height=h)
            if c.capacity >= capacity:
                cands.append(c)
    return cands

def brute(capacity, budgets):
    sl, tl = budgets
    feas = [c for c in all_candidates(capacity)
            if (sl is None or c.sig_bytes <= sl) and (tl is None or c.steps <= tl)]
    if not feas:
        raise ValueError
    nd = [c for c in feas if not any(
        o.sig_bytes <= c.sig_bytes and o.steps <= c.steps
        and (o.sig_bytes < c.sig_bytes or o.steps < c.steps) for o in feas)]
    uniq = list(dict.fromkeys(nd))
    uniq.sort(key=lambda c: (c.steps, c.sig_bytes, c.capacity - capacity, c.scheme,
                             c.w is not None, c.w, c.height is not None, c.height))
    return tuple(uniq)

cases = [(None, 10**9), (10**9, None), (2048, None), (None, 1005), (None, 8670), (2300, 9000), (1088, 8670), (8192, None)]
