assert scheme_frontier(1, (None, 10**9)) == scheme_frontier(1, (None, 10**9))

# capacity 1: both ends of the trade-off present
f = scheme_frontier(1, (None, 10**9))
print("capacity=1 frontier:")
for p in f:
    print(" ", p.scheme, p.w, p.height, "sig", p.sig_bytes, "steps", p.steps)
assert f[0] == profile("lamport")          # speed end: 0 steps
assert f[-1] == profile("wots", w=8)       # size end: 1088 bytes

# errors
for bad_cap in (0, -1, 257, 1.0, True, False, None, "1"):
